package com.emos.attentionfollowthrough.infrastructure;
import com.emos.attentionfollowthrough.application.FollowUpAttentionPort;import com.emos.operationalobservation.domain.OperationalCaseId;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Component;import java.sql.Timestamp;import java.time.Instant;import java.util.UUID;
@Component @ConditionalOnProperty(name="emos.persistence.enabled",havingValue="true",matchIfMissing=true)
public class JdbcFollowUpAttentionPort implements FollowUpAttentionPort{private final JdbcTemplate jdbc;public JdbcFollowUpAttentionPort(JdbcTemplate jdbc){this.jdbc=jdbc;}public void ensureReviewAttention(OperationalCaseId c,Instant now,String reason){var ids=jdbc.query("select id from disposition_obligation where subject_case_id=? and expectation_key='improvement-review' and state in ('PENDING','BREACHED')",(rs,n)->rs.getObject(1,UUID.class),c.value());UUID obligation;if(ids.isEmpty()){obligation=UUID.randomUUID();jdbc.update("insert into disposition_obligation(id,expectation_key,policy_version,subject_case_id,source_resolved_at,deadline,state,breached_at) values(?,'improvement-review',1,?,?,?,'BREACHED',?)",obligation,c.value(),Timestamp.from(now),Timestamp.from(now),Timestamp.from(now));}else obligation=ids.getFirst();jdbc.update("insert into attention_item(id,obligation_id,subject_case_id,reason,state,opened_at) values(?,?,?,?,'OPEN',?) on conflict(obligation_id) do nothing",UUID.randomUUID(),obligation,c.value(),reason,Timestamp.from(now));}public void resolveReviewAttention(OperationalCaseId c,Instant now){jdbc.update("update disposition_obligation set state='SATISFIED' where subject_case_id=? and expectation_key='improvement-review' and state in ('PENDING','BREACHED')",c.value());jdbc.update("update attention_item set state='RESOLVED',resolved_at=? where subject_case_id=? and state='OPEN' and obligation_id in(select id from disposition_obligation where expectation_key='improvement-review')",Timestamp.from(now),c.value());}}
